var style="\n    .p-navigationmenu {\n        display: flex;\n        align-items: center;\n        padding: dt('navigationmenu.padding');\n        gap: dt('navigationmenu.gap');\n    }\n\n    .p-navigationmenu .p-menu-trigger-button {\n        cursor: pointer;\n        display: inline-flex;\n        align-items: center;\n        gap: dt('navigationmenu.base.item.gap');\n        padding: dt('navigationmenu.base.item.padding');\n        font-size: dt('navigationmenu.base.item.font.size');\n        font-weight: dt('navigationmenu.base.item.font.weight');\n        border: 0 none;\n        background: transparent;\n        color: dt('navigationmenu.base.item.color');\n        border-radius: dt('navigationmenu.base.item.border.radius');\n        text-decoration: none;\n        user-select: none;\n        outline: 0 none;\n        transition:\n            background dt('navigationmenu.base.item.transition.duration'),\n            color dt('navigationmenu.base.item.transition.duration');\n    }\n\n    .p-navigationmenu .p-menu-trigger-button:not(:disabled):hover {\n        color: dt('navigationmenu.base.item.focus.color');\n        background: dt('navigationmenu.base.item.focus.background');\n    }\n\n    .p-navigationmenu .p-menu-trigger-button:focus-visible {\n        color: dt('navigationmenu.base.item.focus.color');\n        background: dt('navigationmenu.base.item.focus.background');\n    }\n\n    .p-navigationmenu .p-menu-trigger-button[data-open],\n    .p-navigationmenu .p-menu-trigger-button[data-expanded] {\n        color: dt('navigationmenu.base.item.active.color');\n        background: dt('navigationmenu.base.item.active.background');\n    }\n\n    .p-navigationmenu .p-menu-trigger-button:disabled {\n        opacity: 0.6;\n        pointer-events: none;\n    }\n\n    .p-menu-popup[data-instant],\n    .p-menu-popup[data-instant].p-anchored-overlay-enter-active,\n    .p-menu-popup[data-instant].p-anchored-overlay-leave-active {\n        animation: none !important;\n        transition: none !important;\n    }\n";export{style};